class Solution {
  public int minCostToEqualizeArray(int[] nums, int cost1, int cost2) {
    final long MOD = 1_000_000_007L;
    int n = nums.length;
    long max = 0, min = Long.MAX_VALUE, sum = 0;
    for (int x : nums) {
      max = Math.max(max, x);
      min = Math.min(min, x);
      sum += x;
    }
    if (n == 1) return 0;
    // pairing two increments only helps when it beats two single increments
    if (cost2 >= 2L * cost1) return (int) (((n * max - sum) * cost1) % MOD);
    long best = Long.MAX_VALUE;
    for (long target = max; target <= 2 * max; target++) {
      long total = n * target - sum; // increments needed in all
      long biggest = target - min; // increments the smallest element needs
      long pairs = Math.min(total / 2, total - biggest);
      best = Math.min(best, pairs * cost2 + (total - 2 * pairs) * cost1);
    }
    return (int) (best % MOD);
  }
}
